effect.shader:
// k/255 pelo mais perto, montado nos bits do float: o valor exato que a textura de 8 bits devolve ao AM (o
// `floor(..)/255.0` vai pelo recíproco e erra o último bit — ver `am-color-balance.xml`).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;                                                    // o bit mais alto de n
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;                      // entre 2^23 e 2^24
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

// Um pixel do fundo como a textura `comp` do AM o guarda: pré-multiplicado, em 8 bits.
vec4 fundoPre(ivec2 px) {
    vec4 c = texelFetch(comp, px, 0);
    if (c.a >= 1.0) return c;
    vec3 k = floor(c.rgb * c.a * 255.0 + 0.5);
    return vec4(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b), c.a);
}

// O `texture2DCv(comp.texture, uv)` do AM: o filtro linear da GPU no fundo pré-multiplicado, CLAMP_TO_EDGE. Com os
// 4 pixels opacos é o filtro da própria GPU; senão, à mão nos 4 pixels pré-multiplicados.
vec4 fundoNoPonto(vec2 uv) {
    vec4 g = texture(comp, uv);
    if (g.a >= 1.0) return g;
    ivec2 T = textureSize(comp, 0);
    vec2 p = uv * vec2(T) - 0.5;
    vec2 i = floor(p);
    vec2 f = p - i;
    ivec2 a = ivec2(i);
    ivec2 m = T - 1;
    vec4 c00 = fundoPre(clamp(a, ivec2(0), m));
    vec4 c10 = fundoPre(clamp(a + ivec2(1, 0), ivec2(0), m));
    vec4 c01 = fundoPre(clamp(a + ivec2(0, 1), ivec2(0), m));
    vec4 c11 = fundoPre(clamp(a + ivec2(1, 1), ivec2(0), m));
    return mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);
}

const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);

void main() {
    // A UV da tela do fundo (t = 0 embaixo, a da tela do AM); na tela (`stage="screen"`) é o próprio acScreenNorm.
    vec2 tela = acTela(acScreenNorm);

    // Daqui até a `amostra`, a conta do AM na mesma ordem (o `sample` dele é palavra reservada no GLSL ES 3.00).
    vec2 adjOffs = offs / 1000.0;
    adjOffs.x *= acTamanhoDaCamada.x/acTamanhoDaCamada.y * -1.0;

    // A camada pré-multiplicada em 8 bits, como o AM a entrega (no opaco, a própria cor).
    vec4 texColor = texture(inputImg, acScreenNorm);
    if (texColor.a < 1.0) {
        vec3 k = floor(texColor.rgb * texColor.a * 255.0 + 0.5);
        texColor.rgb = vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
    }
    float luminance = dot(texColor.rgb, luminanceWeighting);
    float px = 0.0;
    float py = 0.0;

    if( typex==0 ) {
        px = luminance;
    } else if( typex == 1 ) {
        px = texColor.r;
    } else if( typex == 2 ) {
        px = texColor.g;
    } else if( typex == 3 ) {
        px = texColor.b;
    } else {
        adjOffs *= 0.0;
    }

    if( typey==0 ) {
        py = luminance;
    } else if( typey == 1 ) {
        py = texColor.r;
    } else if( typey == 2 ) {
        py = texColor.g;
    } else if( typey == 3 ) {
        py = texColor.b;
    } else {
        adjOffs *= 0.0;
    }

    if( fromctr ) {
        px = (px-0.5)*2.0;
        py = (py-0.5)*2.0;
    }
    if( invert ) {
        px = 1.0-px;
        py = 1.0-py;
    }

    vec2 p = vec2(px,py);

    adjOffs *= p * texColor.a;

    vec2 amostra = tela + adjOffs;
    vec4 saida;
    if(edges==0) {
        saida = fundoNoPonto(amostra);
    } else if(edges==1) {
        amostra = vec2(1.0,1.0) - abs(mod(amostra,vec2(2.0,2.0))-vec2(1.0,1.0));
        saida = fundoNoPonto(amostra) * texColor.a;
    } else if(edges==2) {
        if( amostra.x < 0.0 || amostra.x > 1.0 || amostra.y < 0.0 || amostra.y > 1.0 ) {
            saida = vec4(0.0,0.0,0.0,0.0);
        } else {
            saida = fundoNoPonto(amostra) * texColor.a;
        }
    } else if(edges==3) {
        amostra = mod(amostra,vec2(1.0,1.0));
        saida = fundoNoPonto(amostra) * texColor.a;
    } else {
        saida = fundoNoPonto(amostra) * texColor.a;
    }

    // Pré-multiplicada, como o AM; o Nova guarda reta.
    fragColor = saida.a > 0.0 ? vec4(saida.rgb / saida.a, saida.a) : vec4(0.0);
}
